quartileSizes.sql:
SELECT spend_quartile, COUNT(*) AS customers FROM (
  SELECT NTILE(4) OVER (ORDER BY spend DESC) AS spend_quartile FROM customers
) GROUP BY 1 ORDER BY 1;

fifthSizes.sql:
SELECT bucket, COUNT(*) AS customers FROM (
  SELECT NTILE(5) OVER (ORDER BY spend DESC) AS bucket FROM customers
) GROUP BY 1 ORDER BY 1;
